import cffi
import os

ffi = cffi.FFI()
ffi.cdef("""
void *EVP_CIPHER_CTX_new(void);
void EVP_CIPHER_CTX_free(void *c);
const void *EVP_chacha20_poly1305(void);
int EVP_EncryptInit_ex(void *ctx, const void *cipher, void *impl, const unsigned char *key, const unsigned char *iv);
int EVP_EncryptUpdate(void *ctx, unsigned char *out, int *outl, const unsigned char *in, int inl);
int EVP_EncryptFinal_ex(void *ctx, unsigned char *out, int *outl);
int EVP_CIPHER_CTX_ctrl(void *ctx, int type, int arg, void *ptr);
""")

# find libcrypto
import ctypes.util
lib_name = ctypes.util.find_library('crypto')
if not lib_name:
    # fallback
    if os.path.exists('/usr/lib/x86_64-linux-gnu/libcrypto.so'):
        lib_name = '/usr/lib/x86_64-linux-gnu/libcrypto.so'
    elif os.path.exists('/usr/local/lib/libcrypto.dylib'):
        lib_name = '/usr/local/lib/libcrypto.dylib'
    else:
        lib_name = 'libcrypto.so'

lib = ffi.dlopen(lib_name)

EVP_CTRL_AEAD_SET_IVLEN = 0x09
EVP_CTRL_AEAD_GET_TAG = 0x10

class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        associated_data = problem["associated_data"]

        ctx = lib.EVP_CIPHER_CTX_new()
        cipher = lib.EVP_chacha20_poly1305()

        lib.EVP_EncryptInit_ex(ctx, cipher, ffi.NULL, ffi.NULL, ffi.NULL)
        lib.EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, len(nonce), ffi.NULL)
        lib.EVP_EncryptInit_ex(ctx, ffi.NULL, ffi.NULL, key, nonce)

        outl = ffi.new("int *")
        if associated_data:
            lib.EVP_EncryptUpdate(ctx, ffi.NULL, outl, associated_data, len(associated_data))

        out = bytearray(len(plaintext))
        out_buf = ffi.from_buffer(out)
        lib.EVP_EncryptUpdate(ctx, out_buf, outl, plaintext, len(plaintext))

        lib.EVP_EncryptFinal_ex(ctx, ffi.NULL, outl)

        tag = bytearray(16)
        tag_buf = ffi.from_buffer(tag)
        lib.EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_buf)

        lib.EVP_CIPHER_CTX_free(ctx)

        # The benchmark checks for bytes
        return {"ciphertext": bytes(out), "tag": bytes(tag)}
